mapper.select:
Select 코드 as code -- 코드 ,그룹코드 as groupCode -- 그룹코드 ,seqno as seqno -- seqno ,코드분류 as codeGb -- 코드분류 ,날짜 as date -- 날짜 ,금액 as amt -- 금액 ,비고 as cnte -- 비고 ,계정코드1 as code1 -- 계정코드1 ,계정코드2 as code2 -- 계정코드2 ,계정코드3 as code3 -- 계정코드3 ,년도 as year -- 년도 ,to_char(입력일자, 'YYYYMMDDHH24MISS') as inputDate -- 입력일자 ,workcd as workcd -- workcd ,uer_yn as uerYn -- uer_yn From 지출_groupitem where 코드 = #{code}
AND 그룹코드 = #{groupCode}
order by 코드

Select 코드 as code -- 코드 ,그룹코드 as groupCode -- 그룹코드 ,seqno as seqno -- seqno ,코드분류 as codeGb -- 코드분류 ,날짜 as date -- 날짜 ,금액 as amt -- 금액 ,비고 as cnte -- 비고 ,계정코드1 as code1 -- 계정코드1 ,계정코드2 as code2 -- 계정코드2 ,계정코드3 as code3 -- 계정코드3 ,년도 as year -- 년도 ,to_char(입력일자, 'YYYYMMDDHH24MISS') as inputDate -- 입력일자 ,workcd as workcd -- workcd ,uer_yn as uerYn -- uer_yn From 지출_groupitem where 1 = 1
AND 그룹코드 = #{groupCode}
order by 그룹코드,seqno,코드

mapper.update:
update 지출_groupitem Set 그룹코드 = #{groupCode} -- 그룹코드 , seqno = #{seqno} -- seqno , 코드분류 = #{codeGb} -- 코드분류 , 날짜 = #{date} -- 날짜 , 금액 = #{amt} -- 금액 , 비고 = #{cnte} -- 비고
, 계정코드1 = #{code1}
, 계정코드2 = #{code2}
, 계정코드3 = #{code3}
, 년도 = #{year} -- 년도 , 입력일자 = #{inputDate} -- 입력일자 , workcd = #{workcd} -- workcd where 코드 = #{code}
